// PostgREST returns a JSON array; n8n normally splits that into one item
// per row already, but handle both shapes defensively (same pattern as
// 05_n8n_e2e_audit's 'Normalize Lead' node).
const rows = Array.isArray($json) ? $json : ($json.items || $json.data || [$json]);
const row = rows[0];
if (!row || !row.id) {
  throw new Error('No current AimVersion found for AIMFOLD_COLLECTIQ_AIM_ID — has 20260819120200_seed_collectiq_aim.sql been applied and approved?');
}
return [{json: {aim_version_id: row.id, compiled_spec: row.compiled_spec}}];

// Replaces the hardcoded search list from v0.2's 'Build Source Searches'.
// Each input item is one active aim_signal_hypotheses row for the current
// AimVersion. The mapping from source_key to an actual Apify actor env var
// is connector-level plumbing, not Aim data, so it stays here — same as
// v0.2 kept actor IDs in env vars rather than in the search list.
const CONNECTORS = {
  linkedin_jobs_apify: { actorEnvVar: 'APIFY_LINKEDIN_ACTOR_ID', tag: 'linkedin' },
  indeed_jobs_apify: { actorEnvVar: 'APIFY_INDEED_ACTOR_ID', tag: 'indeed' }
};

const out = [];
for (const item of $input.all()) {
  const h = item.json;
  const connector = CONNECTORS[h.source_key];
  if (!connector) {
    // Unknown source_key with no actor mapping yet — skip this one
    // hypothesis rather than failing the whole run (a failure in one
    // source must not break the Aim).
    continue;
  }
  const params = h.connector_params || {};
  out.push({json: {
    source: connector.tag,
    actor: $env[connector.actorEnvVar],
    query: params.keyword,
    location: params.location
  }});
}
return out;

const x=$json;
// Verified against live Apify actor input schemas (jobscrawler~linkedin-jobs-scraper,
// jobscrawler~indeed-jobs-scraper) on 2026-08-16: both actors take the same field
// names — keyword, location, country, maxItems.
//
// v0.3 fix: v0.2 hardcoded country:'US' for every search, including the UK
// credit-controller searches, which contradicts the Aim's own declared
// geography (compiled_spec.geography = ['United States','United Kingdom']).
// Derive country from location instead.
const COUNTRY_BY_LOCATION = { 'United States': 'US', 'United Kingdom': 'GB' };
const input = {
  keyword: x.query,
  location: x.location,
  country: COUNTRY_BY_LOCATION[x.location] || 'US',
  maxItems: Number($env.APIFY_MAX_RESULTS_PER_SEARCH || 50)
};
return [{json:{...x, actor_input:input}}];

const sourceCfg=$('Build Actor Input').item.json;
const rows=Array.isArray($json) ? $json : ($json.items || $json.data || []);

function first(o, keys){
  for(const k of keys){
    const parts=k.split('.');
    let v=o;
    for(const p of parts) v=v?.[p];
    if(v!==undefined && v!==null && v!=='') return v;
  }
  return null;
}

// LinkedIn's public search cards sometimes duplicate the title/company text
// (e.g. "Acme Inc\n...\nAcme Inc") and append UI badges like "Be an early
// applicant" to the location. Collapse whitespace, dedupe exact-repeated
// halves, and strip known badge text before storing.
const BADGE_PHRASES = [/\bbe an early applicant\b/gi, /\bactively hiring\b/gi, /\bpromoted\b/gi];
function clean(s){
  let t = String(s||'').replace(/\s+/g,' ').trim();
  BADGE_PHRASES.forEach(re => { t = t.replace(re, '').trim(); });
  const half = t.length / 2;
  if (Number.isInteger(half)) {
    const a = t.slice(0, half).trim();
    const b = t.slice(half).trim();
    if (a && a === b) t = a;
  }
  return t;
}

return rows.map(r=>{
  const company=first(r,['companyName','company','company_name','employer.name','hiringOrganization.name']);
  const title=first(r,['title','jobTitle','job_title','positionName','name']);
  const loc=first(r,['location','jobLocation','job_location','formattedLocation']);
  const desc=first(r,['description','jobDescription','job_description','descriptionText','text']);
  const url=first(r,['url','jobUrl','job_url','link','applyUrl']);
  const id=first(r,['id','jobId','job_id','jobPostingId']);
  const posted=first(r,['postedDate','postedAt','posted_at','datePosted','publishedAt','postedTime']);
  const company_name=clean(company);
  const job_title=clean(title);
  const job_location=clean(loc);
  const fingerprint=[company_name.toLowerCase(),job_title.toLowerCase(),job_location.toLowerCase()].join('|');
  return {json:{
    source:sourceCfg.source,
    search_query:sourceCfg.query,
    company_name:company_name||null,
    job_title:job_title||null,
    job_location:job_location||null,
    description:clean(desc),
    source_url:url||null,
    source_job_id:id||null,
    posted_at:posted||null,
    fingerprint,
    raw:r
  }};
}).filter(x=>x.json.company_name && x.json.job_title);

// Replaces v0.2's hardcoded regex/points list — now reads compiled_spec.scoring_weights
// from the Aim fetched at the top of this workflow, so scoring changes are a data
// edit (new AimVersion), not a workflow edit.
const scoringWeights = $('Parse Aim Config').first().json.compiled_spec.scoring_weights || [];
const text = `${$json.job_title||''} ${$json.description||''}`.toLowerCase();
let score = 0;
const signals = [];
for (const rule of scoringWeights) {
  const re = new RegExp(rule.pattern);
  if (re.test(text)) {
    score += rule.points;
    signals.push(rule.label);
  }
}
score = Math.min(score, 100);
return [{json: {...$json, prospect_score: score, signals, fit_reason: signals.join(', ')}}];
